    margin-bottom: var(--space-12px);
    padding: var(--space-6px) var(--space-8px);
  }
  .vilda-home-workspace .vhome-visit-title,
  .vilda-home-workspace .vhome-card-heading > span { display: none; }
  .vilda-home-workspace .vhome-visit-meta {
    grid-column: 1;
    justify-self: start;
