    line-height: 20px;
  }
  .vilda-home-workspace .vhome-visit-kicker::after { content: '·'; margin-inline-start: var(--space-6px); }
  .vilda-home-workspace .vhome-history-button {
    grid-column: 2;
    width: 130px;
    min-width: 130px;
    height: 44px;
    min-height: 44px;
