  }
  .vilda-home-workspace .vhome-form-content { padding: var(--space-14px); }
  .vilda-home-workspace .vhome-card-heading { margin-bottom: var(--space-12px); }
  .vilda-home-workspace .vhome-card-heading h2 { font-size: 16px; line-height: 22px; }
  .vilda-home-workspace .vhome-section-title {
    position: absolute;
    width: 1px;
