  .vilda-home-workspace .vhome-fields { margin-bottom: var(--space-10px); }
  .vilda-home-workspace .vhome-fields label { font-size: 13px; line-height: 19px; }
  .vilda-home-workspace #userSection .vhome-fields :is(input, select) { margin-top: var(--space-4px); padding-inline: var(--space-10px); }
  .vilda-home-workspace .vhome-reference { margin-top: var(--space-10px); }
  .vilda-home-workspace .vhome-reference-label {
    display: grid;
    grid-template-columns: 55px minmax(0, 1fr);
    align-items: center;
    gap: var(--space-10px);
