  .vilda-home-workspace .vhome-reference-full { display: none; }
  .vilda-home-workspace .vhome-reference-compact { display: inline; }
  .vilda-home-workspace .vhome-reference-select {
    height: 46px;
    min-height: 46px;
    margin-top: 0;
    padding: var(--space-8px) var(--space-10px);
  }
  .vilda-home-workspace .vhome-extra-data { margin-top: var(--space-12px); }
  .vilda-home-workspace .vhome-data-shortcuts { gap: var(--space-10px); }
  .vilda-home-workspace #tannerToggleBtn.vhome-input-shortcut {
    height: auto !important;
