  .vilda-home-workspace .vhome-shortcut-title { min-height: 0; }
  .vilda-home-workspace .vhome-shortcut-status { font-size: 13px; }
  .vilda-home-workspace .vhome-input-shortcut > svg { width: 14px; height: 14px; right: 8px; top: 11px; }
  .vilda-home-workspace .vhome-form-actions { margin-top: var(--space-12px); padding-top: var(--space-12px); }
  .vilda-home-workspace .vhome-form-actions :is(#clearAllDataBtn, #metabolicSummaryBtn) {
    min-height: 48px;
